    op.execute(
        "CREATE FUNCTION qrm_account_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN \n        INSERT INTO read_bucket_state\n            (tenant_id,advertiser_id,kind,bucket,source_revision,derived_revision,observed_at)\n        SELECT tenant_id,advertiser_id,kind,bucket,1,1,clock_timestamp()\n        FROM (SELECT tenant_id,advertiser_id,'directory'::varchar AS kind,DATE '1970-01-01' AS bucket FROM (SELECT n.tenant_id,n.advertiser_id FROM new_rows n\n        JOIN old_rows o USING (tenant_id,advertiser_id)\n        WHERE (n.name,n.currency,n.timezone,n.remote_status) IS DISTINCT FROM\n              (o.name,o.currency,o.timezone,o.remote_status)) k) keys ORDER BY tenant_id,advertiser_id,kind,bucket\n        ON CONFLICT (tenant_id,advertiser_id,kind,bucket) DO UPDATE SET\n            source_revision=read_bucket_state.source_revision+1,\n            observed_at=clock_timestamp(),derived_revision=read_bucket_state.source_revision+1;\n    \n        DELETE FROM ad_entity_read target USING (SELECT obj.tenant_id,obj.advertiser_id,obj.kind,obj.remote_id\n        FROM new_rows n JOIN old_rows o USING (tenant_id,advertiser_id)\n        JOIN ad_object obj ON obj.tenant_id=n.tenant_id AND obj.advertiser_id=n.advertiser_id\n        WHERE n.timezone IS DISTINCT FROM o.timezone) k\n        WHERE target.tenant_id=k.tenant_id AND target.advertiser_id=k.advertiser_id\n            AND target.kind=k.kind AND target.remote_id=k.remote_id;\n        INSERT INTO ad_entity_read (tenant_id,advertiser_id,kind,remote_id,parent_kind,parent_remote_id,name,ad_type,operation_status,review_status,delivery_status,budget_mode,optimization_goal,budget_value,target_roas,roas_bid,created_local_date,observed_at,published_version)\n        SELECT o.tenant_id,o.advertiser_id,o.kind,o.remote_id,o.parent_kind,o.parent_remote_id,\n            o.name,o.ad_type,o.operation_status,o.review_status,o.delivery_status,\n            o.configuration->>'budget_mode',o.configuration->>'optimization_goal',\n            (CASE WHEN ((o.configuration -> 'budget') IS NOT NULL AND (o.configuration -> 'budget') NOT IN ('null'::jsonb, 'false'::jsonb, '\"\"'::jsonb, '[]'::jsonb, '{}'::jsonb) AND NOT (jsonb_typeof((o.configuration -> 'budget')) = 'number' AND ((o.configuration -> 'budget') #>> '{}')::numeric = 0)) THEN (CASE WHEN jsonb_typeof((o.configuration -> 'budget')) = 'number' THEN ((o.configuration -> 'budget') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration -> 'budget')) = 'string' AND btrim((o.configuration -> 'budget') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration -> 'budget') #>> '{}')::numeric END) WHEN ((o.configuration -> 'daily_budget') IS NOT NULL AND (o.configuration -> 'daily_budget') NOT IN ('null'::jsonb, 'false'::jsonb, '\"\"'::jsonb, '[]'::jsonb, '{}'::jsonb) AND NOT (jsonb_typeof((o.configuration -> 'daily_budget')) = 'number' AND ((o.configuration -> 'daily_budget') #>> '{}')::numeric = 0)) THEN (CASE WHEN jsonb_typeof((o.configuration -> 'daily_budget')) = 'number' THEN ((o.configuration -> 'daily_budget') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration -> 'daily_budget')) = 'string' AND btrim((o.configuration -> 'daily_budget') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration -> 'daily_budget') #>> '{}')::numeric END) WHEN ((o.configuration -> 'campaign_daily_budget') IS NOT NULL AND (o.configuration -> 'campaign_daily_budget') NOT IN ('null'::jsonb, 'false'::jsonb, '\"\"'::jsonb, '[]'::jsonb, '{}'::jsonb) AND NOT (jsonb_typeof((o.configuration -> 'campaign_daily_budget')) = 'number' AND ((o.configuration -> 'campaign_daily_budget') #>> '{}')::numeric = 0)) THEN (CASE WHEN jsonb_typeof((o.configuration -> 'campaign_daily_budget')) = 'number' THEN ((o.configuration -> 'campaign_daily_budget') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration -> 'campaign_daily_budget')) = 'string' AND btrim((o.configuration -> 'campaign_daily_budget') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration -> 'campaign_daily_budget') #>> '{}')::numeric END) END),(CASE WHEN ((o.configuration -> 'roas_bid') IS NOT NULL AND (o.configuration -> 'roas_bid') NOT IN ('null'::jsonb, 'false'::jsonb, '\"\"'::jsonb, '[]'::jsonb, '{}'::jsonb) AND NOT (jsonb_typeof((o.configuration -> 'roas_bid')) = 'number' AND ((o.configuration -> 'roas_bid') #>> '{}')::numeric = 0)) THEN (CASE WHEN jsonb_typeof((o.configuration -> 'roas_bid')) = 'number' THEN ((o.configuration -> 'roas_bid') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration -> 'roas_bid')) = 'string' AND btrim((o.configuration -> 'roas_bid') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration -> 'roas_bid') #>> '{}')::numeric END) WHEN ((o.configuration -> 'target_roas') IS NOT NULL AND (o.configuration -> 'target_roas') NOT IN ('null'::jsonb, 'false'::jsonb, '\"\"'::jsonb, '[]'::jsonb, '{}'::jsonb) AND NOT (jsonb_typeof((o.configuration -> 'target_roas')) = 'number' AND ((o.configuration -> 'target_roas') #>> '{}')::numeric = 0)) THEN (CASE WHEN jsonb_typeof((o.configuration -> 'target_roas')) = 'number' THEN ((o.configuration -> 'target_roas') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration -> 'target_roas')) = 'string' AND btrim((o.configuration -> 'target_roas') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration -> 'target_roas') #>> '{}')::numeric END) END),(CASE WHEN jsonb_typeof((o.configuration->'roas_bid')) = 'number' THEN ((o.configuration->'roas_bid') #>> '{}')::numeric WHEN jsonb_typeof((o.configuration->'roas_bid')) = 'string' AND btrim((o.configuration->'roas_bid') #>> '{}') ~ '^[+-]?([0-9]+\\.?[0-9]*|\\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN btrim((o.configuration->'roas_bid') #>> '{}')::numeric END),CASE WHEN EXISTS (SELECT 1 FROM pg_timezone_names tz WHERE tz.name=a.timezone) THEN (CASE WHEN jsonb_typeof((o.configuration->'create_time')) = 'number' THEN (CASE WHEN abs((((o.configuration->'create_time') #>> '{}'))::float8) < 1e11 THEN (to_timestamp((((o.configuration->'create_time') #>> '{}'))::float8) AT TIME ZONE a.timezone)::date END) WHEN jsonb_typeof((o.configuration->'create_time')) = 'string' AND ((o.configuration->'create_time') #>> '{}') ~ '^[0-9]+$' THEN (CASE WHEN abs((((o.configuration->'create_time') #>> '{}'))::float8) < 1e11 THEN (to_timestamp((((o.configuration->'create_time') #>> '{}'))::float8) AT TIME ZONE a.timezone)::date END) WHEN jsonb_typeof((o.configuration->'create_time')) = 'string' AND ((o.configuration->'create_time') #>> '{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?)?$' AND pg_input_is_valid(((o.configuration->'create_time') #>> '{}'), 'timestamp') THEN (((o.configuration->'create_time') #>> '{}')::timestamp)::date WHEN jsonb_typeof((o.configuration->'create_time')) = 'string' AND ((o.configuration->'create_time') #>> '{}') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)$' AND pg_input_is_valid(((o.configuration->'create_time') #>> '{}'), 'timestamptz') THEN (((o.configuration->'create_time') #>> '{}')::timestamptz AT TIME ZONE a.timezone)::date END) END,o.observed_at,o.published_version\n        FROM (SELECT obj.tenant_id,obj.advertiser_id,obj.kind,obj.remote_id\n        FROM new_rows n JOIN old_rows o USING (tenant_id,advertiser_id)\n        JOIN ad_object obj ON obj.tenant_id=n.tenant_id AND obj.advertiser_id=n.advertiser_id\n        WHERE n.timezone IS DISTINCT FROM o.timezone) k JOIN ad_object o ON o.tenant_id=k.tenant_id\n            AND o.advertiser_id=k.advertiser_id AND o.kind=k.kind AND o.remote_id=k.remote_id\n        JOIN advertiser_account a ON a.tenant_id=o.tenant_id AND a.advertiser_id=o.advertiser_id;\n     RETURN NULL; END $$"
    )
    op.execute(
        "CREATE TRIGGER qrm_account_update AFTER UPDATE ON advertiser_account REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION qrm_account_update()"
    )


